import { test } from '@playwright/test';

// Authenticated e2e tests mint a session without Google OAuth.
test.beforeEach(async ({ page }) => {
  await page.request.post('/api/test/session', { headers: { 'x-test-secret': process.env.TEST_SESSION_SECRET! } });
});

